/**
 * WebSocket Client Tests
 * Tests state machine, reconnection logic, message encoding/decoding
 */

import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
import { WebSocketClient, ConnectionState } from './websocket-client';

describe('WebSocketClient', () => {
  let client: WebSocketClient;
  let mockWs: any;
  const TEST_URL = 'ws://localhost:5000/ws';

  beforeEach(() => {
    // Mock WebSocket constructor
    mockWs = {
      close: vi.fn(),
      send: vi.fn(),
      addEventListener: vi.fn(),
      removeEventListener: vi.fn(),
      readyState: WebSocket.CONNECTING,
      onopen: null,
      onclose: null,
      onerror: null,
      onmessage: null,
      binaryType: 'blob',
      CONNECTING: 0,
      OPEN: 1,
      CLOSING: 2,
      CLOSED: 3,
    };

    global.WebSocket = vi.fn(() => mockWs) as any;
    vi.useFakeTimers();
  });

  afterEach(() => {
    vi.clearAllTimers();
    vi.useRealTimers();
    client?.disconnect();
  });

  describe('Connection Lifecycle', () => {
    it('should start in DISCONNECTED state', () => {
      client = new WebSocketClient({ url: TEST_URL });
      expect(client.getState()).toBe(ConnectionState.DISCONNECTED);
    });

    it('should transition to CONNECTING when connect() is called', () => {
      client = new WebSocketClient({ url: TEST_URL });
      const stateListener = vi.fn();
      client.onStateChange(stateListener);

      client.connect();

      expect(client.getState()).toBe(ConnectionState.CONNECTING);
      expect(stateListener).toHaveBeenCalledWith(ConnectionState.CONNECTING);
      expect(global.WebSocket).toHaveBeenCalledWith(TEST_URL);
      expect(mockWs.binaryType).toBe('arraybuffer');
    });

    it('should transition to CONNECTED on WebSocket open', () => {
      client = new WebSocketClient({ url: TEST_URL });
      const stateListener = vi.fn();
      client.onStateChange(stateListener);

      client.connect();
      expect(client.getState()).toBe(ConnectionState.CONNECTING);

      // Simulate WebSocket open
      mockWs.onopen?.();

      expect(client.getState()).toBe(ConnectionState.CONNECTED);
      expect(stateListener).toHaveBeenCalledWith(ConnectionState.CONNECTED);
    });

    it('should transition to ERROR on WebSocket error', () => {
      client = new WebSocketClient({ url: TEST_URL });
      const stateListener = vi.fn();
      client.onStateChange(stateListener);

      client.connect();
      mockWs.onerror?.(new Event('error'));

      expect(client.getState()).toBe(ConnectionState.ERROR);
      expect(stateListener).toHaveBeenCalledWith(ConnectionState.ERROR);
    });

    it('should transition to DISCONNECTED on manual disconnect', () => {
      client = new WebSocketClient({ url: TEST_URL, autoReconnect: false });
      const stateListener = vi.fn();
      client.onStateChange(stateListener);

      client.connect();
      mockWs.onopen?.();
      expect(client.getState()).toBe(ConnectionState.CONNECTED);

      client.disconnect();

      expect(client.getState()).toBe(ConnectionState.DISCONNECTED);
      expect(mockWs.close).toHaveBeenCalled();
      expect(stateListener).toHaveBeenCalledWith(ConnectionState.DISCONNECTED);
    });

    it('should not connect if already CONNECTED', () => {
      client = new WebSocketClient({ url: TEST_URL });
      client.connect();
      mockWs.onopen?.();

      const wsCallCount = (global.WebSocket as any).mock.calls.length;
      client.connect(); // Try to connect again

      expect((global.WebSocket as any).mock.calls.length).toBe(wsCallCount);
    });

    it('should not connect if already CONNECTING', () => {
      client = new WebSocketClient({ url: TEST_URL });
      client.connect();

      const wsCallCount = (global.WebSocket as any).mock.calls.length;
      client.connect(); // Try to connect again

      expect((global.WebSocket as any).mock.calls.length).toBe(wsCallCount);
    });
  });

  describe('Reconnection Logic', () => {
    it('should schedule reconnect on close with autoReconnect=true', () => {
      client = new WebSocketClient({
        url: TEST_URL,
        autoReconnect: true,
        reconnectInterval: 3000,
        maxReconnectAttempts: 5,
      });

      client.connect();
      mockWs.onopen?.();
      mockWs.onclose?.(new CloseEvent('close'));

      expect(client.getState()).toBe(ConnectionState.RECONNECTING);

      // Fast-forward time by 3s (first attempt: delay = 3000ms * 1)
      vi.advanceTimersByTime(3000);

      expect(global.WebSocket).toHaveBeenCalledTimes(2); // Initial + 1 reconnect
    });

    it('should use exponential backoff for reconnect delays (capped)', () => {
      client = new WebSocketClient({
        url: TEST_URL,
        autoReconnect: true,
        reconnectInterval: 1000,
        maxReconnectAttempts: 5,
      });

      client.connect();
      mockWs.onopen?.();

      // First disconnect: attempt 1, delay = 1000ms * 1 = 1000ms
      mockWs.onclose?.(new CloseEvent('close'));
      vi.advanceTimersByTime(1000);
      expect(global.WebSocket).toHaveBeenCalledTimes(2);

      // Second disconnect: attempt 2, delay = 1000ms * 2 = 2000ms
      mockWs.onclose?.(new CloseEvent('close'));
      vi.advanceTimersByTime(2000);
      expect(global.WebSocket).toHaveBeenCalledTimes(3);

      // Third disconnect: attempt 3, delay = 1000ms * 3 = 3000ms (capped)
      mockWs.onclose?.(new CloseEvent('close'));
      vi.advanceTimersByTime(3000);
      expect(global.WebSocket).toHaveBeenCalledTimes(4);

      // Fourth disconnect: attempt 4, delay = 1000ms * 3 = 3000ms (still capped)
      mockWs.onclose?.(new CloseEvent('close'));
      vi.advanceTimersByTime(3000);
      expect(global.WebSocket).toHaveBeenCalledTimes(5);
    });

    it('should stop reconnecting after maxReconnectAttempts', () => {
      client = new WebSocketClient({
        url: TEST_URL,
        autoReconnect: true,
        reconnectInterval: 1000,
        maxReconnectAttempts: 2,
      });

      client.connect();
      mockWs.onopen?.();

      // Attempt 1
      mockWs.onclose?.(new CloseEvent('close'));
      vi.advanceTimersByTime(1000);
      expect(global.WebSocket).toHaveBeenCalledTimes(2);

      // Attempt 2 (max reached)
      mockWs.onclose?.(new CloseEvent('close'));
      vi.advanceTimersByTime(2000);
      expect(global.WebSocket).toHaveBeenCalledTimes(3);

      // Attempt 3 (should not happen)
      mockWs.onclose?.(new CloseEvent('close'));
      vi.advanceTimersByTime(3000);
      expect(global.WebSocket).toHaveBeenCalledTimes(3); // Still 3
      expect(client.getState()).toBe(ConnectionState.DISCONNECTED);
    });

    it('should reset reconnect attempts on successful connection', () => {
      client = new WebSocketClient({
        url: TEST_URL,
        autoReconnect: true,
        reconnectInterval: 1000,
        maxReconnectAttempts: 5,
      });

      client.connect();
      mockWs.onopen?.();

      // First disconnect and reconnect
      mockWs.onclose?.(new CloseEvent('close'));
      vi.advanceTimersByTime(1000);
      mockWs.onopen?.(); // Successful reconnect

      expect(global.WebSocket).toHaveBeenCalledTimes(2);

      // Second disconnect: should start from attempt 1 again (1000ms delay)
      mockWs.onclose?.(new CloseEvent('close'));
      vi.advanceTimersByTime(500); // Not enough time
      expect(global.WebSocket).toHaveBeenCalledTimes(2);

      vi.advanceTimersByTime(500); // Now 1000ms total
      expect(global.WebSocket).toHaveBeenCalledTimes(3);
    });

    it('should not reconnect if autoReconnect=false', () => {
      client = new WebSocketClient({
        url: TEST_URL,
        autoReconnect: false,
      });

      client.connect();
      mockWs.onopen?.();
      mockWs.onclose?.(new CloseEvent('close'));

      vi.advanceTimersByTime(10000);

      expect(global.WebSocket).toHaveBeenCalledTimes(1);
      expect(client.getState()).toBe(ConnectionState.DISCONNECTED);
    });

    it('should clear reconnect timer on manual disconnect', () => {
      client = new WebSocketClient({
        url: TEST_URL,
        autoReconnect: true,
        reconnectInterval: 3000,
      });

      client.connect();
      mockWs.onopen?.();
      mockWs.onclose?.(new CloseEvent('close'));

      // Disconnect before timer fires
      client.disconnect();

      vi.advanceTimersByTime(5000);
      expect(global.WebSocket).toHaveBeenCalledTimes(1); // No reconnect
    });
  });

  describe('Message Handling', () => {
    it('should handle binary messages only', () => {
      client = new WebSocketClient({ url: TEST_URL });
      const consoleSpy = vi.spyOn(console, 'warn').mockImplementation(() => {});

      client.connect();
      mockWs.onopen?.();

      // Send text message (should be ignored)
      mockWs.onmessage?.({ data: 'text message' });
      expect(consoleSpy).toHaveBeenCalledWith('Received non-binary message, ignoring');

      consoleSpy.mockRestore();
    });

    it('should call onAttachResponse handler', () => {
      client = new WebSocketClient({ url: TEST_URL });
      const handler = vi.fn();
      client.setHandlers({ onAttachResponse: handler });

      client.connect();
      mockWs.onopen?.();

      // This test verifies the handler is set and would be called
      // Full Protocol Buffer encoding is tested separately
      expect(client.getState()).toBe(ConnectionState.CONNECTED);
    });

    it('should update sessionId on AttachResponse', () => {
      client = new WebSocketClient({ url: TEST_URL });
      expect(client.getSessionId()).toBe('');

      // Session ID is set via attach() or when receiving AttachResponse
      client.attach('test-session-123', 24, 80);
      expect(client.getSessionId()).toBe('test-session-123');
    });
  });

  describe('Session Operations', () => {
    it('should send attach request with empty sessionId for new session', () => {
      client = new WebSocketClient({ url: TEST_URL, jwtAuth: 'test-jwt' });
      client.connect();
      mockWs.onopen?.();

      client.attach('', 24, 80);

      expect(mockWs.send).toHaveBeenCalled();
      // Verify Protocol Buffer encoding happens (binary data sent)
      const sentData = mockWs.send.mock.calls[0][0];
      expect(sentData instanceof Uint8Array).toBe(true);
    });

    it('should send attach request with sessionId to resume', () => {
      client = new WebSocketClient({ url: TEST_URL, jwtAuth: 'test-jwt' });
      client.connect();
      mockWs.onopen?.();

      client.attach('existing-session-456', 30, 120);

      expect(mockWs.send).toHaveBeenCalled();
      expect(client.getSessionId()).toBe('existing-session-456');
    });

    it('should send input data', () => {
      client = new WebSocketClient({ url: TEST_URL });
      client.connect();
      mockWs.onopen?.();

      client.sendInput('ls -la\n');

      expect(mockWs.send).toHaveBeenCalled();
      const sentData = mockWs.send.mock.calls[0][0];
      expect(sentData instanceof Uint8Array).toBe(true);
    });

    it('should send resize request', () => {
      client = new WebSocketClient({ url: TEST_URL });
      client.connect();
      mockWs.onopen?.();

      client.resize(40, 160);

      expect(mockWs.send).toHaveBeenCalled();
    });

    it('should send detach request and clear sessionId', () => {
      client = new WebSocketClient({ url: TEST_URL });
      client.connect();
      mockWs.onopen?.();
      client.attach('session-789', 24, 80);

      expect(client.getSessionId()).toBe('session-789');

      client.detach();

      expect(mockWs.send).toHaveBeenCalledTimes(2); // attach + detach
      expect(client.getSessionId()).toBe('');
    });

    it('should not send messages when disconnected', () => {
      client = new WebSocketClient({ url: TEST_URL });
      const consoleSpy = vi.spyOn(console, 'warn').mockImplementation(() => {});

      client.sendInput('test');

      expect(mockWs.send).not.toHaveBeenCalled();
      expect(consoleSpy).toHaveBeenCalledWith('Cannot send: WebSocket not connected');

      consoleSpy.mockRestore();
    });
  });

  describe('State Listeners', () => {
    it('should notify all state listeners on state change', () => {
      client = new WebSocketClient({ url: TEST_URL });
      const listener1 = vi.fn();
      const listener2 = vi.fn();

      client.onStateChange(listener1);
      client.onStateChange(listener2);

      client.connect();

      expect(listener1).toHaveBeenCalledWith(ConnectionState.CONNECTING);
      expect(listener2).toHaveBeenCalledWith(ConnectionState.CONNECTING);
    });

    it('should allow unsubscribing from state changes', () => {
      client = new WebSocketClient({ url: TEST_URL });
      const listener = vi.fn();

      const unsubscribe = client.onStateChange(listener);
      client.connect();
      expect(listener).toHaveBeenCalledTimes(1);

      listener.mockClear();
      unsubscribe();

      mockWs.onopen?.();
      expect(listener).not.toHaveBeenCalled();
    });

    it('should handle listener errors gracefully', () => {
      client = new WebSocketClient({ url: TEST_URL });
      const errorListener = vi.fn(() => {
        throw new Error('Listener error');
      });
      const goodListener = vi.fn();
      const consoleSpy = vi.spyOn(console, 'error').mockImplementation(() => {});

      client.onStateChange(errorListener);
      client.onStateChange(goodListener);

      client.connect();

      expect(errorListener).toHaveBeenCalled();
      expect(goodListener).toHaveBeenCalled();
      expect(consoleSpy).toHaveBeenCalled();

      consoleSpy.mockRestore();
    });
  });

  describe('Sequence Numbers', () => {
    it('should increment sequence numbers for each message', () => {
      client = new WebSocketClient({ url: TEST_URL });
      client.connect();
      mockWs.onopen?.();

      client.sendInput('command1');
      client.sendInput('command2');
      client.resize(30, 100);

      expect(mockWs.send).toHaveBeenCalledTimes(3);
    });

    it('should reset sequence number on reconnect', () => {
      client = new WebSocketClient({
        url: TEST_URL,
        autoReconnect: true,
        reconnectInterval: 1000,
      });

      client.connect();
      mockWs.onopen?.();
      client.sendInput('test1');

      // Reconnect
      mockWs.onclose?.(new CloseEvent('close'));
      vi.advanceTimersByTime(1000);
      mockWs.onopen?.();

      client.sendInput('test2');

      // Sequence should be reset (both sends at sequence 1)
      expect(mockWs.send).toHaveBeenCalledTimes(2);
    });
  });
});

