/**
 * Terminal Component Tests
 * Tests xterm.js initialization, resize handling, data callbacks, cleanup
 */

import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
import { render, cleanup } from '@testing-library/react';
import { Terminal } from './Terminal';

describe('Terminal', () => {
  let mockTerm: any;
  let mockFitAddon: any;
  let mockWebglAddon: any;
  let mockWebLinksAddon: any;

  beforeEach(() => {
    // Mock Terminal instance
    mockTerm = {
      open: vi.fn(),
      loadAddon: vi.fn(),
      dispose: vi.fn(),
      onData: vi.fn(),
      onResize: vi.fn(),
      write: vi.fn(),
      writeln: vi.fn(),
      clear: vi.fn(),
    };

    // Mock FitAddon
    mockFitAddon = {
      fit: vi.fn(),
    };

    // Mock WebglAddon
    mockWebglAddon = {
      onContextLoss: vi.fn((callback) => {
        // Store callback for testing
        mockWebglAddon._onContextLoss = callback;
      }),
    };

    // Mock WebLinksAddon
    mockWebLinksAddon = {};

    // Mock module imports
    vi.doMock('@xterm/xterm', () => ({
      Terminal: vi.fn(() => mockTerm),
    }));

    vi.doMock('@xterm/addon-fit', () => ({
      FitAddon: vi.fn(() => mockFitAddon),
    }));

    vi.doMock('@xterm/addon-webgl', () => ({
      WebglAddon: vi.fn(() => mockWebglAddon),
    }));

    vi.doMock('@xterm/addon-web-links', () => ({
      WebLinksAddon: vi.fn(() => mockWebLinksAddon),
    }));
  });

  afterEach(() => {
    cleanup();
    vi.clearAllMocks();
  });

  it('should render terminal container', () => {
    const { container } = render(<Terminal />);
    const terminalDiv = container.firstChild as HTMLElement;

    expect(terminalDiv).toBeTruthy();
    expect(terminalDiv.style.width).toBe('100%');
    expect(terminalDiv.style.height).toBe('100%');
    expect(terminalDiv.style.backgroundColor).toBe('rgb(30, 30, 30)');
  });

  it('should initialize xterm.js on mount', () => {
    render(<Terminal />);

    expect(mockTerm.open).toHaveBeenCalled();
    expect(mockTerm.loadAddon).toHaveBeenCalledWith(mockFitAddon);
    expect(mockTerm.loadAddon).toHaveBeenCalledWith(mockWebLinksAddon);
    expect(mockFitAddon.fit).toHaveBeenCalled();
  });

  it('should load WebGL addon by default', () => {
    render(<Terminal />);

    expect(mockTerm.loadAddon).toHaveBeenCalledWith(mockWebglAddon);
  });

  it('should handle WebGL context loss', () => {
    const { rerender } = render(<Terminal />);

    expect(mockWebglAddon.onContextLoss).toHaveBeenCalled();

    // Simulate WebGL context loss
    const consoleSpy = vi.spyOn(console, 'warn').mockImplementation(() => {});
    mockWebglAddon._onContextLoss?.();

    expect(consoleSpy).toHaveBeenCalledWith(
      'WebGL context lost, falling back to Canvas'
    );

    // Component should re-render without WebGL
    rerender(<Terminal />);

    consoleSpy.mockRestore();
  });

  it('should handle WebGL initialization failure gracefully', () => {
    // Mock WebglAddon to throw on construction
    vi.doMock('@xterm/addon-webgl', () => ({
      WebglAddon: vi.fn(() => {
        throw new Error('WebGL not supported');
      }),
    }));

    const consoleSpy = vi.spyOn(console, 'warn').mockImplementation(() => {});

    render(<Terminal />);

    expect(consoleSpy).toHaveBeenCalledWith(
      expect.stringContaining('WebGL not supported'),
      expect.any(Error)
    );

    consoleSpy.mockRestore();
  });

  it('should call onData callback when terminal receives input', () => {
    const onData = vi.fn();
    render(<Terminal onData={onData} />);

    expect(mockTerm.onData).toHaveBeenCalledWith(onData);
  });

  it('should call onResize callback when terminal is resized', () => {
    const onResize = vi.fn();
    render(<Terminal onResize={onResize} />);

    expect(mockTerm.onResize).toHaveBeenCalled();

    // Simulate resize event from xterm
    const resizeCallback = mockTerm.onResize.mock.calls[0][0];
    resizeCallback({ cols: 80, rows: 24 });

    expect(onResize).toHaveBeenCalledWith(80, 24);
  });

  it('should handle window resize events', () => {
    render(<Terminal />);

    expect(mockFitAddon.fit).toHaveBeenCalledTimes(1); // Initial fit

    // Simulate window resize
    window.dispatchEvent(new Event('resize'));

    expect(mockFitAddon.fit).toHaveBeenCalledTimes(2);
  });

  it('should handle orientation change on mobile', async () => {
    vi.useFakeTimers();

    render(<Terminal />);

    const initialFitCount = mockFitAddon.fit.mock.calls.length;

    // Simulate orientation change
    window.dispatchEvent(new Event('orientationchange'));

    // Should not call fit immediately
    expect(mockFitAddon.fit).toHaveBeenCalledTimes(initialFitCount);

    // Should call fit after 100ms delay
    vi.advanceTimersByTime(100);
    expect(mockFitAddon.fit).toHaveBeenCalledTimes(initialFitCount + 1);

    vi.useRealTimers();
  });

  it('should expose public API on window object', () => {
    render(<Terminal />);

    expect((window as any).terminal).toBeDefined();
    expect((window as any).terminal.write).toBeDefined();
    expect((window as any).terminal.writeln).toBeDefined();
    expect((window as any).terminal.clear).toBeDefined();

    // Test public API calls
    (window as any).terminal.write('test');
    expect(mockTerm.write).toHaveBeenCalledWith('test');

    (window as any).terminal.writeln('line');
    expect(mockTerm.writeln).toHaveBeenCalledWith('line');

    (window as any).terminal.clear();
    expect(mockTerm.clear).toHaveBeenCalled();
  });

  it('should dispose terminal on unmount', () => {
    const { unmount } = render(<Terminal />);

    expect(mockTerm.dispose).not.toHaveBeenCalled();

    unmount();

    expect(mockTerm.dispose).toHaveBeenCalled();
  });

  it('should remove resize event listener on unmount', () => {
    const removeEventListenerSpy = vi.spyOn(window, 'removeEventListener');

    const { unmount } = render(<Terminal />);

    unmount();

    expect(removeEventListenerSpy).toHaveBeenCalledWith(
      'resize',
      expect.any(Function)
    );

    removeEventListenerSpy.mockRestore();
  });

  it('should re-initialize when useWebGL state changes', () => {
    const { rerender } = render(<Terminal />);

    const initialOpenCalls = mockTerm.open.mock.calls.length;

    // Force re-render with useWebGL=false by simulating context loss
    mockWebglAddon._onContextLoss?.();
    rerender(<Terminal />);

    // Should re-initialize terminal
    expect(mockTerm.open.mock.calls.length).toBeGreaterThan(initialOpenCalls);
  });

  it('should handle callbacks changing between renders', () => {
    const onData1 = vi.fn();
    const { rerender } = render(<Terminal onData={onData1} />);

    const onData2 = vi.fn();
    rerender(<Terminal onData={onData2} />);

    // Should re-initialize with new callback
    expect(mockTerm.onData).toHaveBeenCalledWith(onData2);
  });

  it('should configure terminal with correct theme', () => {
    const { Terminal: XTermConstructor } = require('@xterm/xterm');

    render(<Terminal />);

    const constructorCall = XTermConstructor.mock.calls[0][0];
    expect(constructorCall.theme).toBeDefined();
    expect(constructorCall.theme.background).toBe('#1e1e1e');
    expect(constructorCall.theme.foreground).toBe('#d4d4d4');
    expect(constructorCall.scrollback).toBe(10000);
    expect(constructorCall.cursorBlink).toBe(true);
  });
});

