```typescript
/**
 * Request monomind health check
 */
async sendHealthCheckRequest(projectDir: string): Promise<HealthCheckResponse> {
  return new Promise((resolve, reject) => {
    const envelope = {
      sequenceNumber: ++this.sequenceNumber,
      healthCheckRequest: { projectDir }
    };

    // Set one-time handler for response
    const originalHandler = this.messageHandlers.onHealthCheckResponse;
    this.messageHandlers.onHealthCheckResponse = (response) => {
      this.messageHandlers.onHealthCheckResponse = originalHandler;
      resolve(response);
    };

    this.sendEnvelope(envelope);

    // Timeout after 10s
    setTimeout(() => reject(new Error('Health check timeout')), 10000);
  });
}
```

#### 2. Upgrade Request

```typescript
/**
 * Request monomind upgrade
 */
async sendUpgradeRequest(projectDir: string, confirmed: boolean): Promise<UpgradeResponse> {
  return new Promise((resolve, reject) => {
    const envelope = {
      sequenceNumber: ++this.sequenceNumber,
      upgradeRequest: { projectDir, confirmed }
    };

    const originalHandler = this.messageHandlers.onUpgradeResponse;
    this.messageHandlers.onUpgradeResponse = (response) => {
      this.messageHandlers.onUpgradeResponse = originalHandler;
      resolve(response);
    };

    this.sendEnvelope(envelope);

    // Timeout after 60s (upgrade takes time)
    setTimeout(() => reject(new Error('Upgrade timeout')), 60000);
  });
}
```

#### 3. Detection Check (NEW - per SRS §2.4)

```typescript
/**
 * Check if monomind is installed in session's working directory
 */
async sendDetectionRequest(projectDir: string): Promise<DetectionResponse> {
