    const envelope = {
      sequenceNumber: ++this.sequenceNumber,
      detectionRequest: { projectDir }
    };

    const originalHandler = this.messageHandlers.onDetectionResponse;
    this.messageHandlers.onDetectionResponse = (response) => {
      this.messageHandlers.onDetectionResponse = originalHandler;
      resolve(response);
    };

    this.sendEnvelope(envelope);

    setTimeout(() => reject(new Error('Detection timeout')), 5000);
  });
}
```

#### 4. Monitoring Stream Subscription (NEW)

```typescript
/**
 * Subscribe to monitoring data stream (org/agent status updates)
 * Returns unsubscribe function
 */
onMonitoringData(callback: (data: MonitoringData) => void): () => void {
