#### 5. Update MessageHandler Interface

```typescript
export interface MessageHandler {
  onAttachResponse?: (response: AttachResponse) => void;
  onOutputData?: (data: OutputData) => void;
  onErrorResponse?: (error: ErrorResponse) => void;
