import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { InstallPrompt } from './InstallPrompt';

describe('InstallPrompt', () => {
  let mockDeferredPrompt: any;

  beforeEach(() => {
    // Clear localStorage
    localStorage.clear();

    // Mock matchMedia for standalone mode detection
    Object.defineProperty(window, 'matchMedia', {
      writable: true,
      value: vi.fn().mockImplementation(query => ({
        matches: query === '(display-mode: standalone)' ? false : false,
        media: query,
        onchange: null,
        addListener: vi.fn(),
        removeListener: vi.fn(),
        addEventListener: vi.fn(),
        removeEventListener: vi.fn(),
        dispatchEvent: vi.fn(),
      })),
    });

    // Mock beforeinstallprompt event
    mockDeferredPrompt = {
      prompt: vi.fn().mockResolvedValue(undefined),
      userChoice: Promise.resolve({ outcome: 'accepted' }),
    };

    vi.useFakeTimers();
  });

  afterEach(() => {
    vi.useRealTimers();
    localStorage.clear();
  });

  describe('Engagement Tracking', () => {
    it('should increment visit count in localStorage', () => {
      render(<InstallPrompt />);

      expect(localStorage.getItem('monoterminal-visit-count')).toBe('1');

      // Unmount and re-render
      render(<InstallPrompt />);

      expect(localStorage.getItem('monoterminal-visit-count')).toBe('2');
    });

    it('should track engagement time', () => {
      render(<InstallPrompt />);

      // Fast-forward 30 seconds (engagement update interval)
      vi.advanceTimersByTime(30000);

      const engagementTime = parseInt(
        localStorage.getItem('monoterminal-engagement-time') || '0',
        10
      );
      expect(engagementTime).toBeGreaterThan(0);
    });

    it('should not track time when document is hidden', () => {
      render(<InstallPrompt />);

      // Simulate page becoming hidden
      Object.defineProperty(document, 'hidden', {
        writable: true,
        value: true,
      });

      const visibilityEvent = new Event('visibilitychange');
      document.dispatchEvent(visibilityEvent);

      const engagementBefore = parseInt(
        localStorage.getItem('monoterminal-engagement-time') || '0',
        10
      );

      vi.advanceTimersByTime(30000);

      const engagementAfter = parseInt(
        localStorage.getItem('monoterminal-engagement-time') || '0',
        10
      );

      // Engagement should not increase significantly while hidden
      expect(engagementAfter - engagementBefore).toBeLessThan(1000);
    });

    it('should update engagement on cleanup', () => {
      const { unmount } = render(<InstallPrompt />);

      vi.advanceTimersByTime(15000); // 15 seconds

      unmount();

