```rust
// Spawn monomind detection task (SRS §2.4.1)
tokio::spawn({
    let session_arc = session.clone();
    async move {
        use monoterminal_monomind_bridge::detect_monomind;

        let working_dir = {
            let s = session_arc.read().await;
