        };

        match detect_monomind(&working_dir) {
            Ok(detection) if detection.is_monomind => {
                let mut s = session_arc.write().await;
                s.monomind_detected = true;
                tracing::info!(
                    "Monomind detected in session {}: project={}, org={}",
                    s.id,
                    detection.project_root.display(),
                    detection.org_name.as_deref().unwrap_or("unknown")
                );
            }
            Ok(_) => {
                let s = session_arc.read().await;
                tracing::debug!("No monomind detected in session {}", s.id);
            }
            Err(e) => {
                tracing::warn!("Monomind detection failed: {}", e);
            }
        }
    }
});
```

