// Mock xterm.js and addons
const mockTerm = {
  open: vi.fn(),
  loadAddon: vi.fn(),
  dispose: vi.fn(),
  onData: vi.fn((callback) => {
    mockTerm._dataCallback = callback;
  }),
  onResize: vi.fn((callback) => {
    mockTerm._resizeCallback = callback;
  }),
  write: vi.fn(),
  writeln: vi.fn(),
  clear: vi.fn(),
  _dataCallback: null as ((data: string) => void) | null,
  _resizeCallback: null as ((size: { cols: number; rows: number }) => void) | null,
};

const mockFitAddon = {
  fit: vi.fn(),
};

const mockWebglAddon = {
  onContextLoss: vi.fn(),
};

vi.mock('@xterm/xterm', () => ({
  Terminal: vi.fn(() => mockTerm),
}));

vi.mock('@xterm/addon-fit', () => ({
  FitAddon: vi.fn(() => mockFitAddon),
}));

vi.mock('@xterm/addon-webgl', () => ({
  WebglAddon: vi.fn(() => mockWebglAddon),
}));

vi.mock('@xterm/addon-web-links', () => ({
  WebLinksAddon: vi.fn(() => ({})),
}));

describe('Terminal', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockTerm._dataCallback = null;
    mockTerm._resizeCallback = null;
  });

  it('should render terminal container', () => {
    const { container } = render(<Terminal />);
    const terminalDiv = container.firstChild as HTMLElement;

    expect(terminalDiv).toBeTruthy();
    expect(terminalDiv.style.width).toBe('100%');
    expect(terminalDiv.style.height).toBe('100%');
  });

  it('should call onData callback when terminal receives input', () => {
    const onData = vi.fn();
    render(<Terminal onData={onData} />);

    expect(mockTerm.onData).toHaveBeenCalledWith(onData);
  });

  it('should call onResize callback when terminal is resized', () => {
    const onResize = vi.fn();
    render(<Terminal onResize={onResize} />);

    expect(mockTerm.onResize).toHaveBeenCalled();

    // Simulate resize event
    if (mockTerm._resizeCallback) {
      mockTerm._resizeCallback({ cols: 80, rows: 24 });
      expect(onResize).toHaveBeenCalledWith(80, 24);
    }
  });

  it('should initialize terminal and fit addon', () => {
    render(<Terminal />);

    expect(mockTerm.open).toHaveBeenCalled();
    expect(mockTerm.loadAddon).toHaveBeenCalled();
    expect(mockFitAddon.fit).toHaveBeenCalled();
  });

  it('should dispose terminal on unmount', () => {
    const { unmount } = render(<Terminal />);

    expect(mockTerm.dispose).not.toHaveBeenCalled();

    unmount();

    expect(mockTerm.dispose).toHaveBeenCalled();
  });

  it('should expose public API on window object', () => {
    render(<Terminal />);

    expect((window as any).terminal).toBeDefined();
    expect((window as any).terminal.write).toBeDefined();
    expect((window as any).terminal.writeln).toBeDefined();
    expect((window as any).terminal.clear).toBeDefined();
  });

  it('should handle window resize events', () => {
    render(<Terminal />);

    const initialFitCount = mockFitAddon.fit.mock.calls.length;

    window.dispatchEvent(new Event('resize'));

    expect(mockFitAddon.fit.mock.calls.length).toBeGreaterThan(initialFitCount);
  });

  it('should handle orientation change with delay', () => {
    vi.useFakeTimers();

    render(<Terminal />);

    const initialFitCount = mockFitAddon.fit.mock.calls.length;

    window.dispatchEvent(new Event('orientationchange'));

    // Should not call fit immediately
    expect(mockFitAddon.fit.mock.calls.length).toBe(initialFitCount);

    // Should call fit after 100ms delay
    vi.advanceTimersByTime(100);
    expect(mockFitAddon.fit.mock.calls.length).toBeGreaterThan(initialFitCount);

    vi.useRealTimers();
  });
});

/**
 * InstallPrompt Component Tests
 * Tests engagement heuristics, beforeinstallprompt event handling, and user interactions
 */

import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
import { render, screen, waitFor, act } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { InstallPrompt } from './InstallPrompt';

describe('InstallPrompt', () => {
  beforeEach(() => {
    localStorage.clear();

    // Mock matchMedia
    Object.defineProperty(window, 'matchMedia', {
      writable: true,
      value: vi.fn().mockImplementation(query => ({
        matches: false,
        media: query,
        onchange: null,
        addListener: vi.fn(),
        removeListener: vi.fn(),
        addEventListener: vi.fn(),
        removeEventListener: vi.fn(),
        dispatchEvent: vi.fn(),
      })),
    });

    vi.useFakeTimers();
  });

  afterEach(() => {
    vi.useRealTimers();
    localStorage.clear();
  });

  describe('Engagement Tracking', () => {
    it('should increment visit count in localStorage', () => {
      render(<InstallPrompt />);

      expect(localStorage.getItem('monoterminal-visit-count')).toBe('1');
    });

    it('should track engagement time', async () => {
      render(<InstallPrompt />);

      await act(async () => {
        vi.advanceTimersByTime(30000);
      });

      const engagementTime = parseInt(
        localStorage.getItem('monoterminal-engagement-time') || '0',
        10
      );
      expect(engagementTime).toBeGreaterThan(0);
    });

    it('should update engagement on cleanup', () => {
      const { unmount } = render(<InstallPrompt />);

      act(() => {
        vi.advanceTimersByTime(15000);
      });

      unmount();

      const engagement = parseInt(
        localStorage.getItem('monoterminal-engagement-time') || '0',
        10
      );
      expect(engagement).toBeGreaterThan(0);
    });
  });

  describe('beforeinstallprompt Event Handling', () => {
    it('should capture beforeinstallprompt event', async () => {
      render(<InstallPrompt />);

      const mockDeferredPrompt = {
        prompt: vi.fn().mockResolvedValue(undefined),
        userChoice: Promise.resolve({ outcome: 'accepted' }),
        preventDefault: vi.fn(),
      };

      await act(async () => {
        const event = new Event('beforeinstallprompt') as any;
        Object.assign(event, mockDeferredPrompt);
        window.dispatchEvent(event);
      });

      expect(mockDeferredPrompt.preventDefault).toHaveBeenCalled();
    });

    it('should NOT show prompt if visit threshold not met', async () => {
      localStorage.setItem('monoterminal-visit-count', '1');
      localStorage.setItem('monoterminal-engagement-time', String(6 * 60 * 1000));

      render(<InstallPrompt />);

      const mockDeferredPrompt = {
        prompt: vi.fn().mockResolvedValue(undefined),
        userChoice: Promise.resolve({ outcome: 'accepted' }),
        preventDefault: vi.fn(),
      };

      await act(async () => {
        const event = new Event('beforeinstallprompt') as any;
        Object.assign(event, mockDeferredPrompt);
        window.dispatchEvent(event);
      });

      expect(screen.queryByText('Install MONOTERMINAL')).not.toBeInTheDocument();
    });

    it('should NOT show prompt if engagement threshold not met', async () => {
      localStorage.setItem('monoterminal-visit-count', '3');
      localStorage.setItem('monoterminal-engagement-time', String(2 * 60 * 1000));

      render(<InstallPrompt />);

      const mockDeferredPrompt = {
        prompt: vi.fn().mockResolvedValue(undefined),
        userChoice: Promise.resolve({ outcome: 'accepted' }),
        preventDefault: vi.fn(),
      };

      await act(async () => {
        const event = new Event('beforeinstallprompt') as any;
        Object.assign(event, mockDeferredPrompt);
        window.dispatchEvent(event);
      });

      expect(screen.queryByText('Install MONOTERMINAL')).not.toBeInTheDocument();
    });

    it('should show prompt when both thresholds are met', async () => {
      localStorage.setItem('monoterminal-visit-count', '2');
      localStorage.setItem('monoterminal-engagement-time', String(5 * 60 * 1000));

      render(<InstallPrompt />);

      const mockDeferredPrompt = {
        prompt: vi.fn().mockResolvedValue(undefined),
        userChoice: Promise.resolve({ outcome: 'accepted' }),
        preventDefault: vi.fn(),
      };

      await act(async () => {
        const event = new Event('beforeinstallprompt') as any;
        Object.assign(event, mockDeferredPrompt);
        window.dispatchEvent(event);
      });

      await waitFor(() => {
        expect(screen.getByText('Install MONOTERMINAL')).toBeInTheDocument();
      });
    });

    it('should NOT show prompt if previously dismissed', async () => {
      localStorage.setItem('monoterminal-visit-count', '3');
      localStorage.setItem('monoterminal-engagement-time', String(10 * 60 * 1000));
      localStorage.setItem('monoterminal-install-dismissed', 'true');

      render(<InstallPrompt />);

      const mockDeferredPrompt = {
        prompt: vi.fn().mockResolvedValue(undefined),
        userChoice: Promise.resolve({ outcome: 'accepted' }),
        preventDefault: vi.fn(),
      };

      await act(async () => {
        const event = new Event('beforeinstallprompt') as any;
        Object.assign(event, mockDeferredPrompt);
        window.dispatchEvent(event);
      });

      expect(screen.queryByText('Install MONOTERMINAL')).not.toBeInTheDocument();
    });
  });

  describe('User Interactions', () => {
    it('should handle install button click', async () => {
      const user = userEvent.setup({ delay: null });
      localStorage.setItem('monoterminal-visit-count', '3');
      localStorage.setItem('monoterminal-engagement-time', String(10 * 60 * 1000));

      render(<InstallPrompt />);

      const mockDeferredPrompt = {
        prompt: vi.fn().mockResolvedValue(undefined),
        userChoice: Promise.resolve({ outcome: 'accepted' }),
        preventDefault: vi.fn(),
      };

      await act(async () => {
        const event = new Event('beforeinstallprompt') as any;
        Object.assign(event, mockDeferredPrompt);
        window.dispatchEvent(event);
      });

      await waitFor(() => {
        expect(screen.getByText('Install Now')).toBeInTheDocument();
      });

      await user.click(screen.getByText('Install Now'));

      expect(mockDeferredPrompt.prompt).toHaveBeenCalled();
    });

    it('should hide prompt on "Maybe Later" click', async () => {
      const user = userEvent.setup({ delay: null });
      localStorage.setItem('monoterminal-visit-count', '3');
      localStorage.setItem('monoterminal-engagement-time', String(10 * 60 * 1000));

      render(<InstallPrompt />);

      const mockDeferredPrompt = {
        prompt: vi.fn().mockResolvedValue(undefined),
        userChoice: Promise.resolve({ outcome: 'dismissed' }),
        preventDefault: vi.fn(),
      };

      await act(async () => {
        const event = new Event('beforeinstallprompt') as any;
        Object.assign(event, mockDeferredPrompt);
        window.dispatchEvent(event);
      });

      await waitFor(() => {
        expect(screen.getByText('Maybe Later')).toBeInTheDocument();
      });

      await user.click(screen.getByText('Maybe Later'));

      await waitFor(() => {
        expect(screen.queryByText('Install MONOTERMINAL')).not.toBeInTheDocument();
      });

      expect(localStorage.getItem('monoterminal-install-dismissed')).toBeNull();
    });

    it('should permanently dismiss on close button click', async () => {
      const user = userEvent.setup({ delay: null });
      localStorage.setItem('monoterminal-visit-count', '3');
      localStorage.setItem('monoterminal-engagement-time', String(10 * 60 * 1000));

      render(<InstallPrompt />);

      const mockDeferredPrompt = {
        prompt: vi.fn().mockResolvedValue(undefined),
        userChoice: Promise.resolve({ outcome: 'dismissed' }),
        preventDefault: vi.fn(),
      };

      await act(async () => {
        const event = new Event('beforeinstallprompt') as any;
        Object.assign(event, mockDeferredPrompt);
        window.dispatchEvent(event);
      });

      await waitFor(() => {
        expect(screen.getByLabelText('Dismiss')).toBeInTheDocument();
      });

      await user.click(screen.getByLabelText('Dismiss'));

      await waitFor(() => {
        expect(screen.queryByText('Install MONOTERMINAL')).not.toBeInTheDocument();
      });

      expect(localStorage.getItem('monoterminal-install-dismissed')).toBe('true');
    });
  });

  describe('Rendering', () => {
    it('should render null when prompt is not shown', () => {
      const { container } = render(<InstallPrompt />);

      expect(container.firstChild).toBeNull();
    });

    it('should display feature benefits when shown', async () => {
      localStorage.setItem('monoterminal-visit-count', '3');
      localStorage.setItem('monoterminal-engagement-time', String(10 * 60 * 1000));

      render(<InstallPrompt />);

      const mockDeferredPrompt = {
        prompt: vi.fn().mockResolvedValue(undefined),
        userChoice: Promise.resolve({ outcome: 'accepted' }),
        preventDefault: vi.fn(),
      };

      await act(async () => {
        const event = new Event('beforeinstallprompt') as any;
        Object.assign(event, mockDeferredPrompt);
        window.dispatchEvent(event);
      });

      await waitFor(() => {
        expect(screen.getByText(/Launch directly from your desktop/)).toBeInTheDocument();
        expect(screen.getByText(/Native window controls/)).toBeInTheDocument();
        expect(screen.getByText(/Offline app shell/)).toBeInTheDocument();
      });
    });
  });
});
